"""Export the Python-owned registry for external readers; never an input catalogue."""
import json
from pathlib import Path
from docattentionlens.methods.registry import list_methods

destination=Path(__file__).resolve().parents[1]/"library/src/docattentionlens/methods/catalogue.json"
destination.write_text(json.dumps({"schema_version":"0.8.0",
    "source":"Generated by scripts/export_methods.py from single-file method definitions; do not edit.",
    "methods":[m.model_dump(mode="json") for m in list_methods()]},indent=2)+"\n",encoding="utf-8")
print("Exported the Python-owned method registry")
